&lt;/ul&gt;
&lt;p&gt;&lt;strong&gt;&lt;span data-contrast=&quot;auto&quot;&gt;You will be great for this position if you have&lt;/span&gt;&lt;/strong&gt;&lt;span data-contrast=&quot;auto&quot;&gt; &lt;/span&gt;&lt;span data-ccp-props=&quot;{}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;&lt;span class=&quot;TextRun SCXW34047700 BCX8&quot; lang=&quot;EN-US&quot; data-contrast=&quot;auto&quot;&gt;&lt;span class=&quot;NormalTextRun SCXW34047700 BCX8&quot;&gt;A curious and self-driven mindset, always looking for new ways to find people instead of waiting to be told how.&lt;/span&gt;&lt;/span&gt;&lt;span class=&quot;EOP Selected SCXW34047700 BCX8&quot; data-ccp-props=&quot;{&amp;quot;134233117&amp;quot;:false,&amp;quot;134233118&amp;quot;:false,&amp;quot;335559738&amp;quot;:0,&amp;quot;335559739&amp;quot;:0}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;li&gt;&lt;span class=&quot;TextRun SCXW203204017 BCX8&quot; lang=&quot;EN-US&quot; data-contrast=&quot;auto&quot;&gt;&lt;span class=&quot;NormalTextRun SCXW203204017 BCX8&quot;&gt;Some exposure to sourcing or recruiting, but more importantly, a real excitement to develop these skills fast.&lt;/span&gt;&lt;/span&gt;&lt;span class=&quot;EOP Selected SCXW203204017 BCX8&quot; data-ccp-props=&quot;{}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;li&gt;&lt;span class=&quot;TextRun SCXW153615896 BCX8&quot; lang=&quot;EN-US&quot; data-contrast=&quot;auto&quot;&gt;&lt;span class=&quot;NormalTextRun SCXW153615896 BCX8&quot;&gt;A creative approach to problem-solving, especially when it comes to reaching hard-to-find technical profiles for a world-class C++ team.&lt;/span&gt;&lt;/span&gt;&lt;span class=&quot;EOP Selected SCXW153615896 BCX8&quot; data-ccp-props=&quot;{&amp;quot;134233117&amp;quot;:false,&amp;quot;134233118&amp;quot;:false,&amp;quot;335559738&amp;quot;:0,&amp;quot;335559739&amp;quot;:0}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;li&gt;&lt;span class=&quot;TextRun SCXW52985230 BCX8&quot; lang=&quot;EN-US&quot; data-contrast=&quot;auto&quot;&gt;&lt;span class=&quot;NormalTextRun SCXW52985230 BCX8&quot;&gt;A resilient&lt;/span&gt;&lt;span class=&quot;NormalTextRun SCXW52985230 BCX8&quot;&gt;&amp;nbsp;attitude, our C++ hiring bar is extremely high, and even strong candidates sometimes&amp;nbsp;&lt;/span&gt;&lt;span class=&quot;NormalTextRun SCXW52985230 BCX8&quot;&gt;don&#39;t&lt;/span&gt;&lt;span class=&quot;NormalTextRun SCXW52985230 BCX8&quot;&gt;&amp;nbsp;make it through. You take that as motivation, not a setback.&lt;/span&gt;&lt;/span&gt;&lt;span class=&quot;EOP Selected SCXW52985230 BCX8&quot; data-ccp-props=&quot;{}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;li&gt;&lt;span class=&quot;TextRun SCXW255604795 BCX8&quot; lang=&quot;EN-US&quot; data-contrast=&quot;auto&quot;&gt;&lt;span class=&quot;NormalTextRun SCXW255604795 BCX8&quot;&gt;Coachability and openness to feedback from&lt;/span&gt;&lt;span class=&quot;NormalTextRun SCXW255604795 BCX8&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;span class=&quot;NormalTextRun SCXW255604795 BCX8&quot;&gt;Hiring Managers, engineers, and candidates.&amp;nbsp;&lt;/span&gt;&lt;/span&gt;&lt;span class=&quot;EOP Selected SCXW255604795 BCX8&quot; data-ccp-props=&quot;{&amp;quot;134233117&amp;quot;:false,&amp;quot;134233118&amp;quot;:false,&amp;quot;335559738&amp;quot;:0,&amp;quot;335559739&amp;quot;:0}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;li&gt;&lt;span class=&quot;TextRun SCXW92957187 BCX8&quot; lang=&quot;EN-US&quot; data-contrast=&quot;auto&quot;&gt;&lt;span class=&quot;NormalTextRun SCXW92957187 BCX8&quot;&gt;Strong communication skills and the ability to build trust with experienced stakeholders.&amp;nbsp;&lt;/span&gt;&lt;/span&gt;&lt;span class=&quot;EOP Selected SCXW92957187 BCX8&quot; data-ccp-props=&quot;{&amp;quot;134233117&amp;quot;:false,&amp;quot;134233118&amp;quot;:false,&amp;quot;335559738&amp;quot;:0,&amp;quot;335559739&amp;quot;:0}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
